(7674812, 1254146, 65234, '<td valign="top">Mama sure posed nicely for you! The rain and sun make for some nice light and interesting details.</td>', 'Mama sure posed nicely for you! The rain and sun make for some nice light and interesting details.', '2020-09-18 10:08:43.000000', NULL, 1),
(7674813, 1254240, 65234, '<td valign="top">LOVE that light!</td>', 'LOVE that light!', '2020-09-18 10:09:09.000000', NULL, 1),
(7674814, 1254164, 65234, '<td valign="top">Can''t believe she would just sit there with a tempting bone right in front of her! But this is expert, so maybe she didn''t LOL. Good detail throughout and I like that the background frames her subtly, with those faint diagonals drawing my eye to her.</td>', 'Can''t believe she would just sit there with a tempting bone right in front of her! But this is expert, so maybe she didn''t LOL. Good detail throughout and I like that the background frames her subtly, with those faint diagonals drawing my eye to her.', '2020-09-18 10:12:50.000000', NULL, 1),
(7674815, 1253464, 65234, '<td valign="top">Very crowded, that harbor. I''m guessing by the motion blur that the boats were rocking/drifting in many places. I might have cropped out the really blurry bit on the right.</td>', 'Very crowded, that harbor. I''m guessing by the motion blur that the boats were rocking/drifting in many places. I might have cropped out the really blurry bit on the right.', '2020-09-18 10:15:32.000000', NULL, 1),
